import { watchDom } from '../../core/observer';

const HERO_ID = 'ptv-home-hero';

function getCards() {
    return Array.from(document.querySelectorAll(
        '.homePage .card, .homePage .virtualScrollItem'
    ));
}

function getCardImage(card) {
    const img = card.querySelector('img');

    if (img?.currentSrc || img?.src) {
        return img.currentSrc || img.src;
    }

    const bg = card.querySelector('.cardImage, .cardImageContainer');
    const style = bg ? getComputedStyle(bg).backgroundImage : '';
    const match = style.match(/url\((["']?)(.*?)\1\)/);

    return match?.[2] || '';
}

function getCardTitle(card) {
    return (
        card.querySelector('.cardText')?.textContent?.trim()
        || card.querySelector('.cardText-first')?.textContent?.trim()
        || card.querySelector('.cardScalableText')?.textContent?.trim()
        || card.getAttribute('title')
        || card.getAttribute('aria-label')
        || ''
    );
}

function getFeaturedCard() {
    return getCards().find((card) => {
        const title = getCardTitle(card);
        const image = getCardImage(card);

        return title && image && !image.includes('/assets/icons/');
    });
}

function buildHero() {
    const home = document.querySelector('.homePage');
    if (!home) return;

    let hero = document.getElementById(HERO_ID);

    if (!hero) {
        hero = document.createElement('section');
        hero.id = HERO_ID;
        hero.className = 'ptv-home-hero';
        home.prepend(hero);
    }

    const card = getFeaturedCard();

    if (!card) {
        hero.classList.add('ptv-hero-empty');
        return;
    }

    const title = getCardTitle(card);
    const image = getCardImage(card);

    hero.classList.remove('ptv-hero-empty');

    hero.innerHTML = `
        <div class="ptv-hero-backdrop" style="background-image:url('${image}')"></div>

        <div class="ptv-hero-content">
            <div class="ptv-hero-kicker">Featured</div>
            <h1 class="ptv-hero-title">${title}</h1>

            <div class="ptv-hero-buttons">
                <button class="ptv-hero-button ptv-hero-play" type="button">
                    <img src="/assets/icons/play.svg" alt="">
                    <span>Play</span>
                </button>

                <button class="ptv-hero-button ptv-hero-info" type="button">
                    More Info
                </button>
            </div>
        </div>
    `;
}

watchDom(buildHero);
buildHero();
